-- MAIT — migration 0001: canonical schema (RFC-001 §4, DATA_MODEL.md, amendments A3, A7, A8, A10)
--
-- Conventions
--   * Primary keys are prefixed, time-sortable text IDs generated by the application (mait_core.ids).
--   * Every tenant-owned table carries organization_id (A7) and exposes UNIQUE (organization_id, id)
--     so child tables reference parents with composite FKs: a row can never point across tenants.
--   * Row-Level Security is defense in depth. The application role sets
--       SET LOCAL mait.organization_id = '<org id>'
--     per transaction. Application-level authorization remains mandatory.
--   * Large payloads live in object storage; tables hold *_ref + digest.

BEGIN;

-- ---------------------------------------------------------------------------
-- Roles
-- ---------------------------------------------------------------------------
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'mait_app') THEN
    CREATE ROLE mait_app NOLOGIN;
  END IF;
END $$;

-- ---------------------------------------------------------------------------
-- Tenancy
-- ---------------------------------------------------------------------------
CREATE TABLE organizations (
  id            text PRIMARY KEY,
  name          text NOT NULL,
  plan          text NOT NULL DEFAULT 'oss',
  settings      jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_at    timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE projects (
  id               text PRIMARY KEY,
  organization_id  text NOT NULL REFERENCES organizations(id),
  name             text NOT NULL,
  environment      text NOT NULL DEFAULT 'development'
                   CHECK (environment IN ('development', 'staging', 'production')),
  created_at       timestamptz NOT NULL DEFAULT now(),
  UNIQUE (organization_id, id),
  UNIQUE (organization_id, name, environment)
);

-- ---------------------------------------------------------------------------
-- Registry: agents, immutable versions, deployments
-- ---------------------------------------------------------------------------
CREATE TABLE agents (
  id               text PRIMARY KEY,
  organization_id  text NOT NULL,
  project_id       text NOT NULL,
  name             text NOT NULL,
  description      text NOT NULL DEFAULT '',
  created_at       timestamptz NOT NULL DEFAULT now(),
  UNIQUE (organization_id, id),
  UNIQUE (project_id, name),
  FOREIGN KEY (organization_id, project_id) REFERENCES projects(organization_id, id)
);

CREATE TABLE policies (
  id               text PRIMARY KEY,
  organization_id  text NOT NULL,
  project_id       text NOT NULL,
  name             text NOT NULL,
  version          integer NOT NULL CHECK (version > 0),
  language         text NOT NULL DEFAULT 'mait-rules-v1' CHECK (language IN ('mait-rules-v1', 'cedar')),
  policy_document  text NOT NULL,
  digest           text NOT NULL,
  created_at       timestamptz NOT NULL DEFAULT now(),
  UNIQUE (organization_id, id),
  UNIQUE (project_id, name, version),
  FOREIGN KEY (organization_id, project_id) REFERENCES projects(organization_id, id)
);

CREATE TABLE tool_definitions (
  id                    text PRIMARY KEY,
  organization_id       text NOT NULL,
  project_id            text NOT NULL,
  name                  text NOT NULL,             -- e.g. refunds.request
  version               text NOT NULL,             -- semver of the tool contract
  description           text NOT NULL DEFAULT '',
  effect                text NOT NULL
                        CHECK (effect IN ('read', 'idempotent_write', 'side_effect', 'destructive')),
  input_schema          jsonb NOT NULL,
  output_schema         jsonb,
  idempotency_supported boolean NOT NULL DEFAULT false,
  reconciliation_supported boolean NOT NULL DEFAULT false,
  approval_required     boolean NOT NULL DEFAULT false,
  timeout_seconds       integer NOT NULL DEFAULT 30 CHECK (timeout_seconds > 0),
  transport             jsonb NOT NULL DEFAULT '{"kind":"native"}'::jsonb, -- native | mcp | http
  credentials_ref       text,                      -- secret://… never a raw secret
  digest                text NOT NULL,
  created_at            timestamptz NOT NULL DEFAULT now(),
  UNIQUE (organization_id, id),
  UNIQUE (project_id, name, version),
  FOREIGN KEY (organization_id, project_id) REFERENCES projects(organization_id, id),
  CHECK (credentials_ref IS NULL OR credentials_ref LIKE 'secret://%')
);

CREATE TABLE agent_versions (
  id                   text PRIMARY KEY,
  organization_id      text NOT NULL,
  agent_id             text NOT NULL,
  version              text NOT NULL,
  spec                 jsonb NOT NULL,             -- canonical, fully resolved spec
  spec_digest          text NOT NULL,              -- sha256 of canonical spec JSON
  artifact_digest      text NOT NULL,              -- source tarball or OCI image digest
  runtime_compat       text NOT NULL,              -- mait SDK/runtime compatibility range
  integration_level    smallint NOT NULL CHECK (integration_level BETWEEN 0 AND 3),
  adapter              text NOT NULL DEFAULT 'native',
  adapter_capabilities jsonb NOT NULL DEFAULT '{}'::jsonb,
  policy_id            text,
  created_at           timestamptz NOT NULL DEFAULT now(),
  UNIQUE (organization_id, id),
  UNIQUE (agent_id, version),
  FOREIGN KEY (organization_id, agent_id) REFERENCES agents(organization_id, id),
  FOREIGN KEY (organization_id, policy_id) REFERENCES policies(organization_id, id)
);

-- Pinned tool versions per agent version (immutability: tool contract changes => new agent version)
CREATE TABLE agent_version_tools (
  organization_id    text NOT NULL,
  agent_version_id   text NOT NULL,
  tool_definition_id text NOT NULL,
  PRIMARY KEY (agent_version_id, tool_definition_id),
  FOREIGN KEY (organization_id, agent_version_id) REFERENCES agent_versions(organization_id, id),
  FOREIGN KEY (organization_id, tool_definition_id) REFERENCES tool_definitions(organization_id, id)
);

-- Immutability is enforced in the database, not only by convention (ADR-007).
CREATE FUNCTION mait_forbid_update() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  RAISE EXCEPTION '% rows are immutable', TG_TABLE_NAME USING ERRCODE = 'check_violation';
END $$;

CREATE TRIGGER agent_versions_immutable BEFORE UPDATE ON agent_versions
  FOR EACH ROW EXECUTE FUNCTION mait_forbid_update();
CREATE TRIGGER tool_definitions_immutable BEFORE UPDATE ON tool_definitions
  FOR EACH ROW EXECUTE FUNCTION mait_forbid_update();
CREATE TRIGGER policies_immutable BEFORE UPDATE ON policies
  FOR EACH ROW EXECUTE FUNCTION mait_forbid_update();

CREATE TABLE deployments (
  id                text PRIMARY KEY,
  organization_id   text NOT NULL,
  agent_id          text NOT NULL,
  agent_version_id  text NOT NULL,
  environment       text NOT NULL CHECK (environment IN ('development', 'staging', 'production')),
  status            text NOT NULL CHECK (status IN ('pending', 'canary', 'active', 'superseded', 'rolled_back')),
  traffic_percent   smallint NOT NULL DEFAULT 100 CHECK (traffic_percent BETWEEN 0 AND 100),
  promoted_by       text,
  evaluation_run_id text,
  created_at        timestamptz NOT NULL DEFAULT now(),
  UNIQUE (organization_id, id),
  FOREIGN KEY (organization_id, agent_id) REFERENCES agents(organization_id, id),
  FOREIGN KEY (organization_id, agent_version_id) REFERENCES agent_versions(organization_id, id)
);
-- At most one active deployment per agent+environment.
CREATE UNIQUE INDEX deployments_one_active
  ON deployments (agent_id, environment) WHERE status = 'active';

-- ---------------------------------------------------------------------------
-- Executions: projection, journal, tasks, checkpoints
-- ---------------------------------------------------------------------------
CREATE TABLE executions (
  id                 text PRIMARY KEY,
  organization_id    text NOT NULL,
  agent_id           text NOT NULL,
  agent_version_id   text NOT NULL,
  deployment_id      text,
  status             text NOT NULL CHECK (status IN (
                       'CREATED', 'QUEUED', 'RUNNING', 'WAITING_FOR_TOOL', 'WAITING_FOR_APPROVAL',
                       'RETRY_WAIT', 'SUSPENDED', 'COMPLETED', 'FAILED', 'CANCELLED')),
  status_reason      text,
  integration_level  smallint NOT NULL CHECK (integration_level BETWEEN 0 AND 3),
  sequence           bigint  NOT NULL DEFAULT 0 CHECK (sequence >= 0),       -- last applied event
  lease_generation   bigint  NOT NULL DEFAULT 0 CHECK (lease_generation >= 0), -- fencing token (A3)
  attempt            integer NOT NULL DEFAULT 1 CHECK (attempt >= 1),          -- retries only (A3)
  max_attempts       integer NOT NULL DEFAULT 3 CHECK (max_attempts >= 1),
  recoveries         integer NOT NULL DEFAULT 0,                              -- lease expirations
  rerun_of           text,                                                     -- re-execution (A3)
  parent_execution_id text,                                                    -- future multi-agent
  idempotency_key    text,                                                     -- API run creation
  input_ref          text NOT NULL,
  output_ref         text,
  budget             jsonb NOT NULL,
  usage              jsonb NOT NULL DEFAULT '{"steps":0,"tool_calls":0,"cost_usd":0,"reserved_usd":0}'::jsonb,
  created_at         timestamptz NOT NULL DEFAULT now(),
  started_at         timestamptz,
  finished_at        timestamptz,
  UNIQUE (organization_id, id),
  UNIQUE (organization_id, idempotency_key),
  FOREIGN KEY (organization_id, agent_id) REFERENCES agents(organization_id, id),
  FOREIGN KEY (organization_id, agent_version_id) REFERENCES agent_versions(organization_id, id),
  FOREIGN KEY (organization_id, deployment_id) REFERENCES deployments(organization_id, id),
  FOREIGN KEY (organization_id, rerun_of) REFERENCES executions(organization_id, id),
  FOREIGN KEY (organization_id, parent_execution_id) REFERENCES executions(organization_id, id),
  CHECK ((status IN ('COMPLETED', 'FAILED', 'CANCELLED')) = (finished_at IS NOT NULL))
);
CREATE INDEX executions_by_agent ON executions (organization_id, agent_id, created_at DESC);
CREATE INDEX executions_active ON executions (organization_id, status)
  WHERE status NOT IN ('COMPLETED', 'FAILED', 'CANCELLED');

CREATE TABLE execution_events (
  organization_id   text NOT NULL,
  execution_id      text NOT NULL,
  sequence          bigint NOT NULL CHECK (sequence > 0),
  event_id          text NOT NULL UNIQUE,      -- writer-generated; dedupes redelivery
  schema_version    smallint NOT NULL DEFAULT 1,
  type              text NOT NULL,
  is_transition     boolean NOT NULL,
  lease_generation  bigint NOT NULL,
  occurred_at       timestamptz NOT NULL DEFAULT now(),
  payload           jsonb NOT NULL DEFAULT '{}'::jsonb,  -- small, redacted
  payload_ref       text,                                 -- object storage for > 16 KiB
  payload_digest    text,
  PRIMARY KEY (execution_id, sequence),
  FOREIGN KEY (organization_id, execution_id) REFERENCES executions(organization_id, id)
);

-- The journal is append-only (ADR-006).
CREATE TRIGGER execution_events_append_only BEFORE UPDATE OR DELETE ON execution_events
  FOR EACH ROW EXECUTE FUNCTION mait_forbid_update();

CREATE TABLE workers (
  id                text PRIMARY KEY,
  pool              text NOT NULL DEFAULT 'default',
  hostname          text NOT NULL,
  version           text NOT NULL,
  capabilities      jsonb NOT NULL DEFAULT '{}'::jsonb,
  started_at        timestamptz NOT NULL DEFAULT now(),
  last_heartbeat_at timestamptz NOT NULL DEFAULT now()
);

-- Durable work queue (A8). Not a source of truth: it can be rebuilt from executions + journal.
CREATE TABLE execution_tasks (
  id                text PRIMARY KEY,
  organization_id   text NOT NULL,
  execution_id      text NOT NULL,
  kind              text NOT NULL CHECK (kind IN ('run', 'retry', 'resume', 'approval_timeout', 'reconcile')),
  state             text NOT NULL CHECK (state IN ('ready', 'leased', 'done', 'dead')),
  pool              text NOT NULL DEFAULT 'default',
  priority          smallint NOT NULL DEFAULT 0,
  available_at      timestamptz NOT NULL DEFAULT now(),   -- doubles as durable timer
  worker_id         text REFERENCES workers(id),
  lease_generation  bigint,
  lease_expires_at  timestamptz,
  created_at        timestamptz NOT NULL DEFAULT now(),
  FOREIGN KEY (organization_id, execution_id) REFERENCES executions(organization_id, id),
  CHECK ((state = 'leased') = (worker_id IS NOT NULL AND lease_expires_at IS NOT NULL))
);
-- At most one live (ready or leased) task per execution.
CREATE UNIQUE INDEX execution_tasks_one_live
  ON execution_tasks (execution_id) WHERE state IN ('ready', 'leased');
CREATE INDEX execution_tasks_claim
  ON execution_tasks (pool, priority DESC, available_at) WHERE state = 'ready';
CREATE INDEX execution_tasks_expiry
  ON execution_tasks (lease_expires_at) WHERE state = 'leased';

CREATE TABLE checkpoints (
  id               text PRIMARY KEY,
  organization_id  text NOT NULL,
  execution_id     text NOT NULL,
  sequence         bigint NOT NULL,          -- journal position the checkpoint is valid at
  format           text NOT NULL,            -- mait-native-v1 | langgraph | ...
  state_ref        text NOT NULL,
  state_digest     text NOT NULL,
  created_at       timestamptz NOT NULL DEFAULT now(),
  UNIQUE (execution_id, sequence),
  FOREIGN KEY (organization_id, execution_id) REFERENCES executions(organization_id, id),
  FOREIGN KEY (execution_id, sequence) REFERENCES execution_events(execution_id, sequence)
);

-- ---------------------------------------------------------------------------
-- Tool invocations and approvals
-- ---------------------------------------------------------------------------
CREATE TABLE tool_invocations (
  id                 text PRIMARY KEY,           -- stable logical identity across retries
  organization_id    text NOT NULL,
  execution_id       text NOT NULL,
  tool_definition_id text NOT NULL,
  step_key           text NOT NULL,              -- name#occurrence (A5)
  status             text NOT NULL CHECK (status IN
                       ('PENDING', 'SUBMITTED', 'CONFIRMED', 'REJECTED', 'UNKNOWN', 'DENIED')),
  idempotency_key    text NOT NULL,
  args_digest        text NOT NULL,
  args_ref           text,
  result_ref         text,
  error              jsonb,
  submit_count       integer NOT NULL DEFAULT 0,
  created_at         timestamptz NOT NULL DEFAULT now(),
  updated_at         timestamptz NOT NULL DEFAULT now(),
  UNIQUE (organization_id, id),
  UNIQUE (execution_id, step_key),
  UNIQUE (tool_definition_id, idempotency_key),
  FOREIGN KEY (organization_id, execution_id) REFERENCES executions(organization_id, id),
  FOREIGN KEY (organization_id, tool_definition_id) REFERENCES tool_definitions(organization_id, id)
);

CREATE TABLE approval_requests (
  id                 text PRIMARY KEY,
  organization_id    text NOT NULL,
  execution_id       text NOT NULL,
  tool_invocation_id text,
  args_digest        text,                       -- approval binds to exact arguments (A10)
  policy_id          text,                       -- and to the policy version in force (A10)
  reason             text NOT NULL,
  status             text NOT NULL CHECK (status IN ('pending', 'granted', 'rejected', 'expired')),
  decided_by         text,
  decision_note      text,
  expires_at         timestamptz NOT NULL,
  created_at         timestamptz NOT NULL DEFAULT now(),
  decided_at         timestamptz,
  UNIQUE (organization_id, id),
  FOREIGN KEY (organization_id, execution_id) REFERENCES executions(organization_id, id),
  FOREIGN KEY (organization_id, tool_invocation_id) REFERENCES tool_invocations(organization_id, id),
  FOREIGN KEY (organization_id, policy_id) REFERENCES policies(organization_id, id),
  CHECK ((status = 'pending') = (decided_at IS NULL))
);

-- ---------------------------------------------------------------------------
-- Evaluation
-- ---------------------------------------------------------------------------
CREATE TABLE evaluation_datasets (
  id               text PRIMARY KEY,
  organization_id  text NOT NULL,
  project_id       text NOT NULL,
  name             text NOT NULL,
  version          integer NOT NULL CHECK (version > 0),
  cases_ref        text NOT NULL,              -- versioned scenario file in object storage
  cases_digest     text NOT NULL,
  case_count       integer NOT NULL,
  created_at       timestamptz NOT NULL DEFAULT now(),
  UNIQUE (organization_id, id),
  UNIQUE (project_id, name, version),
  FOREIGN KEY (organization_id, project_id) REFERENCES projects(organization_id, id)
);
CREATE TRIGGER evaluation_datasets_immutable BEFORE UPDATE ON evaluation_datasets
  FOR EACH ROW EXECUTE FUNCTION mait_forbid_update();

CREATE TABLE evaluation_runs (
  id                        text PRIMARY KEY,
  organization_id           text NOT NULL,
  agent_version_id          text NOT NULL,
  baseline_agent_version_id text,
  dataset_id                text NOT NULL,
  evaluator_config          jsonb NOT NULL,
  status                    text NOT NULL CHECK (status IN ('queued', 'running', 'completed', 'failed', 'cancelled')),
  summary                   jsonb,
  gate_decision             text CHECK (gate_decision IN ('pass', 'fail', 'inconclusive')),
  created_at                timestamptz NOT NULL DEFAULT now(),
  finished_at               timestamptz,
  UNIQUE (organization_id, id),
  FOREIGN KEY (organization_id, agent_version_id) REFERENCES agent_versions(organization_id, id),
  FOREIGN KEY (organization_id, baseline_agent_version_id) REFERENCES agent_versions(organization_id, id),
  FOREIGN KEY (organization_id, dataset_id) REFERENCES evaluation_datasets(organization_id, id)
);

ALTER TABLE deployments
  ADD FOREIGN KEY (organization_id, evaluation_run_id) REFERENCES evaluation_runs(organization_id, id);

CREATE TABLE evaluation_results (
  id                 text PRIMARY KEY,
  organization_id    text NOT NULL,
  evaluation_run_id  text NOT NULL,
  case_id            text NOT NULL,
  execution_id       text,                     -- evidence comes from a real execution
  scores             jsonb NOT NULL,           -- {evaluator: {score, passed, critical, rationale_ref}}
  critical_failure   boolean NOT NULL DEFAULT false,
  created_at         timestamptz NOT NULL DEFAULT now(),
  UNIQUE (evaluation_run_id, case_id, execution_id),
  FOREIGN KEY (organization_id, evaluation_run_id) REFERENCES evaluation_runs(organization_id, id),
  FOREIGN KEY (organization_id, execution_id) REFERENCES executions(organization_id, id)
);

-- ---------------------------------------------------------------------------
-- Row-Level Security (defense in depth, SECURITY.md §2)
-- ---------------------------------------------------------------------------
CREATE FUNCTION mait_current_org() RETURNS text LANGUAGE sql STABLE AS $$
  SELECT nullif(current_setting('mait.organization_id', true), '')
$$;

DO $$
DECLARE t text;
BEGIN
  FOREACH t IN ARRAY ARRAY[
    'projects', 'agents', 'policies', 'tool_definitions', 'agent_versions', 'agent_version_tools',
    'deployments', 'executions', 'execution_events', 'execution_tasks', 'checkpoints',
    'tool_invocations', 'approval_requests', 'evaluation_datasets', 'evaluation_runs',
    'evaluation_results'
  ] LOOP
    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format(
      'CREATE POLICY tenant_isolation ON %I TO mait_app
         USING (organization_id = mait_current_org())
         WITH CHECK (organization_id = mait_current_org())', t);
    EXECUTE format('GRANT SELECT, INSERT, UPDATE ON %I TO mait_app', t);
  END LOOP;
END $$;

ALTER TABLE organizations ENABLE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON organizations TO mait_app USING (id = mait_current_org());
GRANT SELECT ON organizations TO mait_app;
GRANT SELECT, INSERT, UPDATE ON workers TO mait_app;
GRANT INSERT ON execution_events TO mait_app;  -- explicit: no UPDATE/DELETE semantics (trigger-enforced)

COMMIT;
